style.css:
@-moz-document domain("slickdeals.net") {
/* 01. Wallpaper / page baseline */
html {
    background: #010805 !important;
}
body {
    background-color: #021008 !important;
    background-image: linear-gradient(110deg, rgba(0,8,4,.76), rgba(0,14,7,.50), rgba(0,6,3,.78)), url("data:image/webp;base64,") !important;
    background-position: center center !important;
    background-repeat: no-repeat !important;
    background-size: cover !important;
    background-attachment: fixed !important;
    color: #d5ffe4 !important;
    font-family: Consolas, "Lucida Console", "Courier New", monospace !important;
}
/* Strip pale page shells. No image background pixels are modified. */
#container, #wrapper, #page, #main, #content, #body,
#content_wrapper, #content_body, #mainContent, #contentbody,
.contentbody, .contentbody_inner, .page-content, .pageContent,
.page-wrapper, .pageWrapper, .site-content, .siteContent,
.layout, .layout-container, main, [role="main"],
#root, #app, #__next, .page-section, .content-wrapper,
.sqs-layout, .sqs-section, .sqs-block, .sqs-block-content {
    background-color: transparent !important;
    background-image: none !important;
    color: #d5ffe4 !important;
}
#global_feature_content { display: none !important; }
/* Nested feed containers: remove white surfaces rather than covering pictures. */
body div, body section, body article, body aside, body figure,
body ul, body ol, body li, body table, body tbody, body thead,
body tr, body td, body th {
    background-color: transparent !important;
}
/* Stronger background reset where inline framework utility classes exist. */
body div[class], body section[class], body article[class],
body figure[class], body li[class], body main[class] {
    background-color: transparent !important;
}
body .bg-white, body .bg-light, body .bg-gray-50,
body .bg-gray-100, body .bg-neutral-50, body .bg-neutral-100,
body [class*="bgWhite"], body [class*="bg-white"],
body [class*="BackgroundWhite"], body [class*="backgroundWhite"],
body [style*="background-color: white"],
body [style*="background-color:white"],
body [style*="background-color: #fff"],
body [style*="background-color:#fff"],
body [style*="background: #fff"],
body [style*="background:#fff"] {
    background: transparent !important;
}
/* 02. Header, navigation, menu dropdown glass */
header, [role="banner"], #header, #global_header, #globalHeader,
.header, .site-header, .siteHeader, .header-container,
.header-inner, .header-background, .header-nav,
#main_nav, #mainNav, #navbar, .navbar,
nav, [role="navigation"], .primary-nav, .main-nav,
.globalNav, .global-nav, .navigation,
.sqs-announcement-bar, .announcement-bar {
    background: rgba(1, 23, 11, .88) !important;
    color: #d5ffe4 !important;
    border-color: rgba(19, 238, 107, .35) !important;
}
.dropdown-menu, .dropdown, .dropdown-content, .dropdownContent,
.menu, .menuList, .popover, .popover-content,
[role="menu"], [role="listbox"], .mega-menu, .megaMenu,
.nav-dropdown, .navDropdown, .mobile-menu, .mobileMenu,
.flyout, .flyout-menu, .autocomplete, .autocomplete-results,
.search-suggestions, .searchSuggestions, .search-dropdown,
.header-menu, .header-menu-nav {
    background: rgba(2, 25, 12, .94) !important;
    color: #e1ffec !important;
    border: 1px solid rgba(22, 238, 107, .44) !important;
    border-radius: 9px !important;
    box-shadow: 0 10px 23px rgba(0,0,0,.47) !important;
}
/* 03. Card faces / current and older deal grids */
.dealitem, .dealCard, .dealCardV3, .dealCardGrid,
.dealCardListView, .dealCardContainer, .deal-card, .deal-tile,
.dealTile, .feedItem, .feed-item, .fpGridBox,
.bp-c-card, .bp-p-socialDealCard,
.bp-p-blueberryDealCard, .bp-p-dealCard,

.frontpageGrid__feedItem,
.categoryPageDealGrid__feedItem, .searchPageGrid__feedItem,
body [data-type="fpdeal"], body [role="article"],
body main article, body [role="main"] article,
.card, .panel, .widget, .module, .box,
.panel-default, .well, .section-panel, .list-group-item {
    background: rgba(2, 26, 13, .88) !important;
    color: #e1ffea !important;
    border: 1px solid rgba(26, 236, 109, .32) !important;
    border-radius: 9px !important;
    box-shadow: inset 0 1px rgba(164,255,192,.06), 0 4px 15px rgba(0,0,0,.24) !important;
}
/* Darken generic generated grid tiles, common in /embed. */
body [class*="Grid"] > article, body [class*="grid"] > article,
body [class*="Grid"] > li, body [class*="grid"] > li,
body [class*="grid"] > div[class],
body [class*="Grid"] > div[class],
body [class*="feed"] > article,
body [class*="Feed"] > article,
body [role="list"] > li {
    background: rgba(2, 26, 13, .87) !important;
    border-color: rgba(22, 232, 105, .34) !important;
    color: #dcffe9 !important;
}
/* Correct white-on-white info panels within cards. */
body .bp-c-card_content *, body .dealCard__content *,
body .dealCardV3__content *, body .dealCardGrid__content *,
body [class*="DealCard"] [class*="content"],
body [class*="dealCard"] [class*="content"],
body [class*="Card"] [class*="Footer"],
body [class*="card"] [class*="footer"],
body [class*="card"] [class*="detail"],
body [class*="card"] [class*="info"] {
    background-color: transparent !important;
    background-image: none !important;
}
/* Mildly translucent media staging frames: actual product images stay original. */
body .dealCard__image, body .dealCard__imageContainer,
body .dealImage, body .deal-image, body .productImage,
body .product-image, body .bp-c-card_image,
body [class*="ImageContainer"], body [class*="imageContainer"],
body [class*="ImageWrapper"], body [class*="imageWrapper"],
body [class*="MediaWrapper"], body [class*="mediaWrapper"],
body [class*="image-background"], body [class*="image-wrapper"] {
    background-color: rgba(6, 25, 13, .44) !important;
}
/* 03A. Keep the OUTER deal card frame; remove all stacked borders INSIDE it.
   v1.3 broadly matched classes containing DealCard, including its title, price,
   author row, merchant row and image holder. These are content, not new cards.
   The selectors below only affect descendants, never the outer card itself.
   They do not alter img pixels, src, or opacity. */
body .dealitem *, body .dealCard *, body .dealCardV3 *,
body .dealCardGrid *, body .dealCardListView *,
body .dealCardContainer *, body .deal-card *,
body .deal-tile *, body .dealTile *, body .feedItem *,
body .feed-item *, body .fpGridBox *, body .bp-c-card *,
body .bp-p-socialDealCard *, body .bp-p-blueberryDealCard *,
body .bp-p-dealCard *, body .frontpageGrid__feedItem *,
body .categoryPageDealGrid__feedItem *,
body .searchPageGrid__feedItem * {
    border: 0 !important;
    outline: 0 !important;
    box-shadow: none !important;
}
/* Neutralize nested info panes without flattening the root glass card. */
body .dealCard__content, body .dealCardGrid__content,
body .dealCardV3__content, body .bp-c-card_content,
body .dealCard__title, body .dealCard__price,
body .dealCard__footer, body .dealCard__metadata,
body .bp-c-card_body, body .bp-c-card_footer,
body .bp-c-card_header, body .bp-c-card_image {
    background-color: transparent !important;
    background-image: none !important;
    border: 0 !important;
    outline: 0 !important;
    box-shadow: none !important;
}
/* Legacy/plain naming patterns used for inner product tiles. */
body .dealCard [class*="__"], body .dealCardV3 [class*="__"],
body .dealCardGrid [class*="__"], body .bp-c-card [class*="__"],
body .bp-p-blueberryDealCard [class*="__"] {
    border: 0 !important;
    outline: 0 !important;
    box-shadow: none !important;
}

/* 04. Classic forums, sidebars, tabs and promos */
#topics_tab, #HotOffers_innerdiv, .col_topic, #fp3_deals,
#fp3_deals_header, .deal_header_even, .deal_header_odd,
.notice_tan, .notice_tan div, .left_col, .right_col,
.sidebar, .sidebar-content, .sidebarContent, .leftSidebar,
.rightSidebar, .sideBar, .feed, .feed-container, .deal-feed,
.dealFeed, .dealList, .deals-list, .dealGrid, .deal-grid,
.thread-content, .threadContent, .forum-content, .forumContent,
.forum-post, .forumPost, .threadPost, .postbit, .postrow,
.topic, .topicRow, .topic_row, .modal-content, [role="dialog"] {
    background: rgba(2, 24, 12, .82) !important;
    color: #d5ffe4 !important;
    border-color: rgba(30, 236, 110, .31) !important;
}
#fp3_deals_header, #topics_tab, .activetab, .activeTab,
.tab.active, [role="tab"][aria-selected="true"], .selected-tab {
    background: rgba(0, 74, 35, .85) !important;
    color: #e6fff0 !important;
    border-color: #15e973 !important;
}
.dealitem:hover, .dealCard:hover, .deal-card:hover,
.bp-c-card:hover, .bp-p-blueberryDealCard:hover {
    background: rgba(4, 46, 22, .92) !important;
    border-color: #22ed7a !important;
    box-shadow: 0 0 17px rgba(0, 255, 94, .16) !important;
}
/* 05. Typography, metadata and prices */
body, body p, body span, body div, body li, body strong,
body b, body label, body section, body article,
body h1, body h2, body h3, body h4, body h5, body h6,
body td, body th, body figcaption {
    color: #d4fbe0 !important;
}
a, a:link, body a, body a:link { color: #8affb6 !important; }
a:visited { color: #a6dcbc !important; }
a:hover, a:focus { color: #eafff1 !important; }
h1, h2, h3, h4, h5, h6, legend, .title, .heading,
.dealTitle, .deal-title, .thread-title, .forum-title {
    color: #ebfff2 !important;
}
small, time, .muted, .text-muted, .secondary-text,
.meta, .metadata, .subtext, .byline, .dealMeta,
.deal-meta, .posted-time, .postdate,
body [class*="Merchant"], body [class*="merchant"],
body [class*="shipping"], body [class*="Shipping"] {
    color: #9dcbb0 !important;
}
.price, .deal-price, .dealPrice, .final-price,
.current-price, .sale-price, .salePrice,
body [class*="Price"], body [class*="price"] {
    color: #79ffa7 !important;
    font-weight: 700 !important;
}
body [class*="OriginalPrice"], body [class*="originalPrice"],
body del, body s, body strike { color: #abc5b1 !important; }
.notice_tan a { color: #84fbae !important; }
hr, .divider, .separator { border-color: rgba(0,240,104,.24) !important; }
/* 06. Search/forms/buttons */
input, textarea, select, [role="searchbox"], [role="textbox"],
.search-input, .searchInput, .form-control {
    background: rgba(1, 16, 8, .93) !important;
    color: #e0ffec !important;
    border: 1px solid rgba(28, 235, 112, .43) !important;
    border-radius: 7px !important;
    caret-color: #29ff87 !important;
}
input::placeholder, textarea::placeholder { color: #91c4a3 !important; }
input:focus, textarea:focus, select:focus {
    border-color: #28ef82 !important;
    outline-color: #1fe377 !important;
}
button, [role="button"], .btn, .button,
input[type="submit"], input[type="button"],
.sqs-button-element--primary {
    background: rgba(2, 67, 31, .9) !important;
    color: #edfff2 !important;
    border: 1px solid rgba(42, 246, 127, .55) !important;
    border-radius: 7px !important;
}
button:hover, [role="button"]:hover, .btn:hover,
.button:hover, input[type="submit"]:hover {
    background: rgba(2, 109, 47, .95) !important;
    color: #ffffff !important;
}
input[type="checkbox"], input[type="radio"] { accent-color: #1cf77d !important; }
/* 07. lp.slickdeals.net landing page and its iframe element */
#siteWrapper, #siteWrapper main, #siteWrapper .page-section,
#siteWrapper .content-wrapper, #siteWrapper .sqs-layout,
#siteWrapper .sqs-section, #siteWrapper .sqs-block,
#siteWrapper .sqs-block-content {
    background-color: transparent !important;
    background-image: none !important;
}
#siteWrapper header, #siteWrapper .header,
#siteWrapper .header-inner, #siteWrapper .header-background,
#siteWrapper .header-nav {
    background: rgba(0, 26, 12, .88) !important;
}
/* 08. Product photographs: never tint or fade image pixels */
img, picture, video, canvas,
body img, body picture img, body a:hover img {
    opacity: 1 !important;
    filter: none !important;
    mix-blend-mode: normal !important;
}
/* 09. Scrollbars */
::-webkit-scrollbar { width: 11px; height: 11px; }
::-webkit-scrollbar-track { background: #06140a; }
::-webkit-scrollbar-thumb {
    background: #126b36; border: 2px solid #06140a;
    border-radius: 10px;
}
::-webkit-scrollbar-thumb:hover { background: #27bb63; }


/* 10. v1.5 / Same single-outline glass styling for carousel deal cards.
   Outlines do not change carousel slide width or height; this avoids
   shifting or clipping the carousel track. Preserve each product image. */
body .swiper-slide,
body .slick-slide,
body .splide__slide,
body [class*="carousel"] [class*="DealCard"],
body [class*="Carousel"] [class*="DealCard"],
body [class*="carousel"] [class*="dealCard"],
body [class*="Carousel"] [class*="dealCard"],
body [class*="Carousel"] [class*="deal-card"],
body [class*="carousel"] [class*="deal-card"],
body [class*="carousel"] .bp-c-card,
body [class*="Carousel"] .bp-c-card,
body [class*="carousel"] .bp-p-blueberryDealCard,
body [class*="Carousel"] .bp-p-blueberryDealCard,
body [class*="carousel"] .bp-p-socialDealCard,
body [class*="Carousel"] .bp-p-socialDealCard {
    background: rgba(2, 26, 13, .84) !important;
    outline: 1px solid rgba(33, 226, 110, .42) !important;
    outline-offset: -1px !important;
    border-radius: 10px !important;
    box-shadow: 0 4px 16px rgba(0, 0, 0, .20) !important;
}
/* Where the slide wraps its card in one or two extra layout elements,
   keep their backgrounds clear instead of stacking extra glass boxes. */
body .swiper-slide > div,
body .slick-slide > div,
body .splide__slide > div,
body [class*="carousel"] [class*="Card"] [class*="__"],
body [class*="Carousel"] [class*="Card"] [class*="__"],
body [class*="carousel"] [class*="dealCard"] [class*="__"],
body [class*="Carousel"] [class*="dealCard"] [class*="__"] {
    border: 0 !important;
    outline: 0 !important;
    box-shadow: none !important;
}
/* Some frontpage carousels use a slide inner wrapper as the card itself.
   Style only the immediate child of each slide, not every nested block. */
body .swiper-slide > div,
body .slick-slide > div,
body .splide__slide > div {
    background: rgba(2, 26, 13, .32) !important;
    border-radius: 9px !important;
}
body .swiper-slide:hover,
body .slick-slide:hover,
body .splide__slide:hover,
body [class*="carousel"] [class*="DealCard"]:hover,
body [class*="Carousel"] [class*="DealCard"]:hover,
body [class*="carousel"] [class*="dealCard"]:hover,
body [class*="Carousel"] [class*="dealCard"]:hover {
    background-color: rgba(5, 39, 20, .90) !important;
    outline-color: rgba(38, 245, 122, .72) !important;
    box-shadow: 0 0 16px rgba(0, 255, 100, .12) !important;
}
/* 11. v1.5 / Right rail ('Popular Deals', Trending, sidebar widgets).
   Give the whole column one glass shell rather than boxed subsections. */
body aside,
body [role="complementary"],
body .rightSidebar,
body .right-sidebar,
body .rightRail,
body .right-rail,
body .rightColumn,
body .right-column,
body [class*="RightSidebar"],
body [class*="rightSidebar"],
body [class*="RightRail"],
body [class*="rightRail"],
body [class*="PopularDeals"],
body [class*="popularDeals"],
body [class*="popular-deals"] {
    background: rgba(2, 26, 13, .83) !important;
    color: #dbffeb !important;
    border: 1px solid rgba(33, 235, 110, .43) !important;
    border-radius: 10px !important;
    box-shadow: 0 5px 18px rgba(0, 0, 0, .23) !important;
}
/* Remove the bright header slab seen above 'Popular Deals'. */
body aside > header,
body aside > div:first-child,
body [role="complementary"] > header,
body .rightSidebar > header,
body .rightRail > header,
body .rightColumn > header,
body [class*="PopularDeals"] > header,
body [class*="popularDeals"] > header,
body [class*="PopularDeals"] [class*="Header"],
body [class*="PopularDeals"] [class*="header"],
body [class*="popularDeals"] [class*="Header"],
body [class*="popularDeals"] [class*="header"],
body [class*="RightRail"] [class*="header"],
body [class*="rightRail"] [class*="header"],
body [class*="RightSidebar"] [class*="header"],
body [class*="rightSidebar"] [class*="header"] {
    background: rgba(0, 39, 18, .48) !important;
    color: #a5ffc5 !important;
    border: 0 !important;
    outline: 0 !important;
    box-shadow: none !important;
}
/* One border on the outer rail: no boxes or strong white separators
   around each deal title, metadata line, vote row, or list item. */
body aside article,
body aside li,
body aside section,
body aside .card,
body aside .panel,
body aside .widget,
body aside .list-group-item,
body [role="complementary"] li,
body [role="complementary"] article,
body .rightSidebar li,
body .rightRail li,
body .rightColumn li,
body [class*="PopularDeals"] li,
body [class*="popularDeals"] li,
body [class*="PopularDeals"] article,
body [class*="popularDeals"] article,
body [class*="PopularDeals"] [class*="Item"],
body [class*="popularDeals"] [class*="item"],
body [class*="RightRail"] [class*="Item"],
body [class*="rightRail"] [class*="item"] {
    background: transparent !important;
    border: 0 !important;
    outline: 0 !important;
    box-shadow: none !important;
}
/* Avoid fresh outlined inner boxes for nested header/body/footer sections. */
body aside [class*="__header"],
body aside [class*="__body"],
body aside [class*="__footer"],
body aside [class*="__title"],
body [class*="PopularDeals"] [class*="__"],
body [class*="popularDeals"] [class*="__"] {
    background-color: transparent !important;
    border: 0 !important;
    outline: 0 !important;
    box-shadow: none !important;
}
body aside h2,
body aside h3,
body [class*="PopularDeals"] h2,
body [class*="popularDeals"] h2,
body [class*="RightRail"] h2,
body [class*="rightRail"] h2 {
    color: #9dffc4 !important;
    background-color: transparent !important;
}
/* 12. v1.5 / Guarantee unfiltered media in these regions. */
body .swiper-slide img,
body .slick-slide img,
body .splide__slide img,
body aside img,
body [role="complementary"] img,
body [class*="PopularDeals"] img,
body [class*="popularDeals"] img {
    opacity: 1 !important;
    filter: none !important;
    mix-blend-mode: normal !important;
    background-image: none !important;
}


/* 13. v1.6 / Right-rail pale voting and coupon-redemption counter chips.
   These selectors avoid product photos, coupon logos, and discount-code tags.
   Suppress WHITE backgrounds on numeric pills only, not whole sidebar rows. */
body aside [class*="voteCount"],
body aside [class*="VoteCount"],
body aside [class*="vote-count"],
body aside [class*="ratingCount"],
body aside [class*="RatingCount"],
body aside [class*="scoreCount"],
body aside [class*="ScoreCount"],
body aside [class*="thumbCount"],
body aside [class*="ThumbCount"],
body aside [class*="redemptionCount"],
body aside [class*="RedemptionCount"],
body aside [class*="redemption-count"],
body aside [class*="couponCount"],
body aside [class*="CouponCount"],
body aside [class*="vote-count"],
body aside [class*="rating-count"],
body [role="complementary"] [class*="voteCount"],
body [role="complementary"] [class*="VoteCount"],
body [role="complementary"] [class*="redemption"],
body [role="complementary"] [class*="Redemption"],
body .rightRail [class*="Count"],
body .rightRail [class*="count"],
body .rightSidebar [class*="Count"],
body .rightSidebar [class*="count"],
body .rightColumn [class*="Count"],
body .rightColumn [class*="count"],
body [class*="RightRail"] [class*="Count"],
body [class*="rightRail"] [class*="count"],
body [class*="RightSidebar"] [class*="Count"],
body [class*="rightSidebar"] [class*="count"],
body [class*="right-rail"] [class*="count"],
body [class*="right-column"] [class*="count"],
body [class*="TrendingDeals"] [class*="Count"],
body [class*="trendingDeals"] [class*="count"],
body [class*="trending-deals"] [class*="count"],
body [class*="FeaturedCoupons"] [class*="Redemption"],
body [class*="featuredCoupons"] [class*="redemption"],
body [class*="featured-coupons"] [class*="redemption"],
body aside [class*="Redemptions"],
body aside [class*="redemptions"] {
    background: rgba(3, 42, 19, .90) !important;
    color: #dbffe6 !important;
    border: 1px solid rgba(36, 217, 104, .18) !important;
    border-radius: 3px !important;
    outline: 0 !important;
    box-shadow: none !important;
    text-shadow: none !important;
}
/* Utility-class and inline white fills on small sidebar labels. */
body aside span.bg-white,
body aside span.bg-light,
body aside span.bg-gray-50,
body aside span.bg-gray-100,
body aside span.bg-neutral-50,
body aside span.bg-neutral-100,
body aside small.bg-white,
body aside label.bg-white,
body aside output.bg-white,
body aside span[style*="background: white"],
body aside span[style*="background:white"],
body aside span[style*="background: #fff"],
body aside span[style*="background:#fff"],
body aside span[style*="background-color: white"],
body aside span[style*="background-color:white"],
body aside span[style*="background-color: #fff"],
body aside span[style*="background-color:#fff"],
body aside span[style*="background-color: rgb(255"],
body aside span[style*="background-color:rgb(255"],
body [role="complementary"] span.bg-white,
body [role="complementary"] small.bg-white,
body .rightRail span.bg-white,
body .rightSidebar span.bg-white,
body .rightColumn span.bg-white,
body [class*="RightRail"] span.bg-white,
body [class*="rightRail"] span.bg-white,
body [class*="TrendingDeals"] span.bg-white,
body [class*="trendingDeals"] span.bg-white,
body [class*="FeaturedCoupons"] span.bg-white,
body [class*="featuredCoupons"] span.bg-white {
    background: rgba(3, 42, 19, .90) !important;
    color: #ddffe8 !important;
    border-color: rgba(36, 217, 104, .18) !important;
    box-shadow: none !important;
    text-shadow: none !important;
}
/* Protect text inside numeric chips from pale text set by page styles. */
body aside [class*="voteCount"] span,
body aside [class*="VoteCount"] span,
body aside [class*="redemptionCount"] span,
body aside [class*="RedemptionCount"] span,
body aside [class*="redemptions"] span,
body [class*="RightRail"] [class*="Count"] span,
body [class*="rightRail"] [class*="count"] span {
    color: #ddffe8 !important;
    text-shadow: none !important;
}
/* Keep coupon brand tiles and original artwork exactly as supplied. */
body aside img,
body aside picture,
body [role="complementary"] img,
body [role="complementary"] picture {
    opacity: 1 !important;
    filter: none !important;
    mix-blend-mode: normal !important;
}


/* 14. v1.7 / FULL-WIDTH SITE FOOTER - replace the large gray bottom area.
   Only the site footer is targeted; deal-card footers are deliberately excluded.
   No extra inner borders and no alterations to logo or download badge images. */
body footer,
body [role="contentinfo"],
body #footer,
body #globalFooter,
body #global_footer,
body #footerContainer,
body #footerWrapper,
body .siteFooter,
body .site-footer,
body .globalFooter,
body .global-footer,
body .slickdealsFooter,
